namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F\n2. Roll out dough on floured surface\n3. Spread crushed tomatoes\n4. Add torn mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil and olive oil",
            Ratings = [5, 4, 5, 4]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale\nEgg yolks\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti al dente\n2. Crisp guanciale in pan\n3. Mix yolks with grated pecorino and pepper\n4. Toss hot pasta with guanciale\n5. Remove from heat, stir in egg mixture\n6. Serve immediately",
            Ratings = [5, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
            Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or broil chicken until charred\n3. Sauté onion, garlic, ginger\n4. Add tomato sauce and spices\n5. Simmer, add cream\n6. Add chicken pieces and heat through",
            Ratings = [5, 4, 5, 5]
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nTofu\nBean sprouts\nPeanuts\nLime\nTamarind paste\nFish sauce\nEggs\nGreen onions",
            Steps = "1. Soak rice noodles in warm water\n2. Press and cube tofu, pan fry until golden\n3. Scramble eggs in wok\n4. Add noodles and sauce (tamarind, fish sauce, sugar)\n5. Toss with bean sprouts and tofu\n6. Serve with peanuts and lime",
            Ratings = [4, 4, 3]
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef, drain fat\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm tortillas\n5. Assemble with toppings\n6. Serve with salsa and sour cream",
            Ratings = [4, 5, 4]
        },
        new()
        {
            Id = 6, Title = "Green Curry", Category = "Thai",
            Ingredients = "Coconut milk\nGreen curry paste\nChicken breast\nBamboo shoots\nThai basil\nFish sauce\nPalm sugar\nJasmine rice",
            Steps = "1. Heat coconut cream until oil separates\n2. Fry curry paste until fragrant\n3. Add chicken slices, cook through\n4. Add coconut milk, bamboo shoots\n5. Season with fish sauce and sugar\n6. Serve over jasmine rice with Thai basil",
            Ratings = [5, 4]
        },
    ];

    private int _nextId = 7;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

